<?php

namespace App\Modules\Production\Presentation\Http\Controllers;

use App\Http\Controllers\Controller; use App\Modules\Identity\Domain\Models\AuthorizationRequest; use App\Modules\Production\Application\CompleteProduction; use App\Modules\Production\Application\Data\ActualConsumptionData; use App\Modules\Production\Application\Data\ActualOutputData; use App\Modules\Production\Application\Data\CompleteProductionData; use App\Modules\Production\Application\Data\LaborHoursData; use App\Modules\Production\Domain\Models\ProductionOrder; use App\Modules\Production\Presentation\Http\Requests\CompleteProductionRequest; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Carbon;
class CompleteProductionController extends Controller { public function __invoke(CompleteProductionRequest $request,ProductionOrder $production,CompleteProduction $action):RedirectResponse { $data=$request->validated();$authId=$data['manual_labor_authorization_id']??null;$action->execute($production,new CompleteProductionData(Carbon::parse($data['completed_at']),(string)$data['actual_dough_quantity'],(string)$data['waste_quantity'],$request->user(),array_map(ActualConsumptionData::fromArray(...),$data['consumptions']),array_map(ActualOutputData::fromArray(...),$data['outputs']),array_map(LaborHoursData::fromArray(...),$data['labor_hours']??[]),isset($data['manual_labor_amount'])?(int)$data['manual_labor_amount']:null,$data['manual_labor_reason']??null,$authId?AuthorizationRequest::query()->findOrFail($authId):null));return to_route('production.show',$production)->with('success','Producción completada e inventario actualizado.'); } }
